function serveImg(req, res) {
  const u = new URL(req.url, 'http://x').searchParams.get('u') || '';
  if (!/^https:\/\/([\w-]+\.)*(ytimg\.com|googleusercontent\.com|ggpht\.com|mzstatic\.com|scdn\.co|spotifycdn\.com)\//.test(u)) { res.writeHead(400); return res.end(); }
  const f = path.join(imgDir(), crypto.createHash('sha1').update(u).digest('hex') + '.img');
  fs.readFile(f, (err, data) => {
    if (!err && data.length) { res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'max-age=604800' }); return res.end(data); }
    fetch(u).then(async (r) => {
      const b = Buffer.from(await r.arrayBuffer());
      if (r.ok && b.length > 200) fs.writeFile(f, b, () => {});
      res.writeHead(r.status, { 'Content-Type': r.headers.get('content-type') || 'image/jpeg', 'Cache-Control': 'max-age=86400' }); res.end(b);
    }).catch(() => { res.writeHead(504); res.end(); });
  });
}

